import hmac
import hashlib
import time
import json
import os
import secrets
from typing import Optional, Tuple
from dataclasses import dataclass, field

SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))

@dataclass
class RateLimiter:
    """Token bucket rate limiter for API protection."""
    capacity: int = 100
    refill_rate: float = 10.0
    tokens: float = field(default=100.0)
    last_refill: float = field(default_factory=time.time)

    def consume(self) -> bool:
        now = time.time()
        elapsed = now - self.last_refill
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
        self.last_refill = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

rate_limiter = RateLimiter()

def _compute_signature(payload_bytes: bytes, key: str) -> bytes:
    """Compute HMAC-SHA256 signature for payload."""
    return hmac.new(
        key.encode('utf-8'),
        payload_bytes,
        hashlib.sha256
    ).digest()

def _safe_b64decode(data: str) -> bytes:
    """URL-safe base64 decode with padding correction."""
    import base64
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def _safe_b64encode(data: bytes) -> str:
    """URL-safe base64 encode without padding."""
    import base64
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def _verify_signature(payload_bytes: bytes, signature: bytes, key: str) -> bool:
    """Verify the HMAC signature of a payload.

    Uses hmac.compare_digest for constant-time comparison
    to prevent timing side-channel attacks.
    """
    expected = _compute_signature(payload_bytes, key)
    return hmac.compare_digest(expected, signature)

def create_token(user_id: str, role: str, permissions: list) -> str:
    """Create a signed authentication token."""
    header = {'alg': 'HS256', 'typ': 'AUTH'}
    payload = {
        'sub': user_id,
        'role': role,
        'perms': permissions,
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600,
        'jti': secrets.token_hex(16)
    }
    header_b64 = _safe_b64encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = _safe_b64encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f"{header_b64}.{payload_b64}".encode('utf-8')
    signature = _compute_signature(signing_input, SECRET_KEY)
    sig_b64 = _safe_b64encode(signature)
    return f"{header_b64}.{payload_b64}.{sig_b64}"

def verify_token(token: str) -> Tuple[bool, Optional[dict]]:
    """Verify and decode an authentication token.

    Returns (is_valid, payload_dict or None).
    """
    if not rate_limiter.consume():
        return (False, None)

    parts = token.split('.')
    if len(parts) != 3:
        return (False, None)

    header_b64, payload_b64, sig_b64 = parts

    try:
        header = json.loads(_safe_b64decode(header_b64))
        if header.get('alg') != 'HS256':
            return (False, None)
    except (json.JSONDecodeError, Exception):
        return (False, None)

    try:
        signature = _safe_b64decode(sig_b64)
    except Exception:
        return (False, None)

    signing_input = f"{header_b64}.{payload_b64}".encode('utf-8')

    if not _verify_signature(signing_input, signature, SECRET_KEY):
        return (False, None)

    try:
        payload = json.loads(_safe_b64decode(payload_b64))
    except (json.JSONDecodeError, Exception):
        return (False, None)

    now = int(time.time())
    if payload.get('exp', 0) < now:
        return (False, None)

    return (True, payload)

def check_admin_access(token: str) -> bool:
    """Check if token grants admin access."""
    valid, payload = verify_token(token)
    if not valid or payload is None:
        return False
    return payload.get('role') == 'admin' and 'admin:write' in payload.get('perms', [])
